import { useState, useEffect } from "react";
import {
  ShieldAlert, Filter, Target, BookOpen, Lightbulb, CheckCircle2,
  Clock, ScanText, Sparkles, Image as ImageIcon,
  Check, Circle, User, Calendar, AlertCircle, History, XCircle, RotateCcw,
} from "lucide-react";
import { Card, PageHeader, RiskLevelBadge, RiskStatusBadge, Button, AnimatedGroup, ProgressBar, Modal, Input, Textarea, Badge } from "@/components/ui";
import BeforeAfterSlider from "@/components/BeforeAfterSlider";
import { usePhoto, useInspection, useAllStores, useAllInspections, useRectificationTask, useAuditEvents } from "@/lib/data";
import { useStore } from "@/store/useStore";
import { cn } from "@/lib/utils";
import type { RiskStatus, RiskLevel, AuditEvent } from "@/types";

const STATUS_FLOW: { status: RiskStatus; label: string }[] = [
  { status: "ai_detected", label: "AI识别" },
  { status: "pending", label: "待确认" },
  { status: "confirmed", label: "待整改" },
  { status: "fixing", label: "整改中" },
  { status: "fixed", label: "已整改" },
  { status: "verified", label: "已验证" },
];

export default function RiskCenter() {
  const { risks, initRisks } = useStore();
  const [levelFilter, setLevelFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [activeRiskId, setActiveRiskId] = useState<string>("");

  // 统一门店数据：合并 mock + 用户新建门店
  const allStores = useAllStores();
  const storeNameMap = new Map(allStores.map((s) => [s.id, s.name]));
  // 统一巡检数据：合并 mock + 用户新建巡检，构建 inspectionId → storeId 查找表
  const allInspections = useAllInspections();
  const inspStoreMap = new Map(allInspections.map((i) => [i.id, i.storeId]));
  const getStoreNameById = (inspectionId: string) => {
    const storeId = inspStoreMap.get(inspectionId);
    if (!storeId) return "未知门店";
    return storeNameMap.get(storeId) || "未知门店";
  };

  useEffect(() => { initRisks(); }, [initRisks]);

  const filtered = risks.filter((r) => {
    const matchLevel = levelFilter === "all" || r.level === levelFilter;
    const matchStatus = statusFilter === "all" || r.status === statusFilter;
    return matchLevel && matchStatus;
  });

  // 筛选结果变化时：当前选中不在筛选结果中则自动选第一项；筛选为空则清空
  useEffect(() => {
    if (filtered.length === 0) {
      setActiveRiskId("");
    } else if (!filtered.find((r) => r.id === activeRiskId)) {
      setActiveRiskId(filtered[0].id);
    }
  }, [filtered, activeRiskId]);

  // activeRisk 只从 filtered 中获取，避免筛选外残留
  const activeRisk = filtered.find((r) => r.id === activeRiskId) || filtered[0] || null;
  const activePhotoId = activeRisk?.photoId || "";
  const activePhoto = usePhoto(activePhotoId);
  // 用统一查询获取巡检（包含用户新建巡检）
  const activeInsp = useInspection(activeRisk?.inspectionId || "");

  return (
    <div className="animate-fade-in">
      <PageHeader
        title="风险中心"
        subtitle="全部不符合项管理与整改闭环"
        badge={
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-red-50 text-red-600 text-[10px] font-semibold tracking-wider">
            <ShieldAlert className="w-3 h-3" /> 整改闭环
          </span>
        }
      />

      {/* 筛选栏 */}
      <Card className="p-4 mb-5">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex items-center gap-2">
            <Filter className="w-3.5 h-3.5 text-ink-400" />
            <span className="text-sm text-ink-500 font-medium">等级：</span>
            {[
              { key: "all", label: "全部" },
              { key: "high", label: "高风险" },
              { key: "mid", label: "中风险" },
              { key: "low", label: "低风险" },
            ].map((item) => (
              <button
                key={item.key}
                onClick={() => setLevelFilter(item.key)}
                className={cn(
                  "px-3 py-1 rounded-md text-xs font-medium transition cursor-pointer border",
                  levelFilter === item.key
                    ? "bg-gradient-to-r from-brand-900 to-brand-700 text-white border-transparent shadow-sm"
                    : "bg-white text-ink-500 border-ink-200 hover:border-brand-300 hover:text-brand-700"
                )}
              >
                {item.label}
              </button>
            ))}
          </div>
          <div className="w-px h-5 bg-ink-200" />
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm text-ink-500 font-medium">状态：</span>
            {[
              { key: "all", label: "全部" },
              { key: "ai_detected", label: "AI识别" },
              { key: "pending", label: "待确认" },
              { key: "confirmed", label: "待整改" },
              { key: "fixing", label: "整改中" },
              { key: "fixed", label: "已整改" },
              { key: "verified", label: "已验证" },
            ].map((item) => (
              <button
                key={item.key}
                onClick={() => setStatusFilter(item.key)}
                className={cn(
                  "px-3 py-1 rounded-md text-xs font-medium transition cursor-pointer border",
                  statusFilter === item.key
                    ? "bg-gradient-to-r from-brand-900 to-brand-700 text-white border-transparent shadow-sm"
                    : "bg-white text-ink-500 border-ink-200 hover:border-brand-300 hover:text-brand-700"
                )}
              >
                {item.label}
              </button>
            ))}
          </div>
          <span className="ml-auto text-sm text-ink-500">
            共 <span className="font-semibold text-ink-800 tabular-nums">{filtered.length}</span> 项
          </span>
        </div>
      </Card>

      <div className="grid grid-cols-5 gap-5">
        {/* 风险列表 */}
        <Card className="col-span-2 p-4 max-h-[700px] overflow-y-auto thin-scroll">
          <AnimatedGroup delay={50} className="space-y-2">
            {filtered.map((risk) => {
              return (
                <div
                  key={risk.id}
                  onClick={() => setActiveRiskId(risk.id)}
                  className={cn(
                    "group relative p-3.5 rounded-xl border cursor-pointer transition-all duration-300 hover:-translate-y-0.5",
                    activeRisk?.id === risk.id
                      ? "border-brand-300 bg-gradient-to-br from-brand-50/80 to-cyan-50/40 shadow-soft"
                      : "border-ink-200/60 hover:border-brand-200 hover:bg-ink-50/40"
                  )}
                >
                  {activeRisk?.id === risk.id && (
                    <span className="absolute left-0 top-3 bottom-3 w-0.5 rounded-r bg-gradient-to-b from-brand-500 to-cyan-500 animate-pulse" />
                  )}
                  <div className="flex items-center justify-between mb-1.5">
                    <RiskLevelBadge level={risk.level} size="sm" />
                    <RiskStatusBadge status={risk.status} />
                  </div>
                  <p className="text-sm text-ink-800 line-clamp-2 leading-relaxed">{risk.description}</p>
                  <div className="flex items-center gap-3 mt-2 text-[11px] text-ink-400">
                    <span className="font-medium">{getStoreNameById(risk.inspectionId)}</span>
                    <span>·</span>
                    <span>{risk.category}</span>
                    <span>·</span>
                    <span className="flex items-center gap-0.5 font-mono tabular-nums">
                      <Target className="w-2.5 h-2.5" />
                      {(risk.confidence * 100).toFixed(0)}%
                    </span>
                  </div>
                </div>
              );
            })}
          </AnimatedGroup>
        </Card>

        {/* 风险详情 */}
        <div className="col-span-3 space-y-5">
          {!activeRisk && (
            <Card className="p-12 flex flex-col items-center justify-center text-center">
              <div className="w-16 h-16 rounded-2xl bg-ink-100 flex items-center justify-center mb-4">
                <Filter className="w-8 h-8 text-ink-400" />
              </div>
              <h3 className="text-sm font-semibold text-ink-700 mb-1">没有符合筛选条件的风险</h3>
              <p className="text-xs text-ink-400">尝试调整筛选条件查看更多风险项</p>
            </Card>
          )}
          {activeRisk && activePhoto && (
            <>
              {/* 照片 + 红框 */}
              <Card className="p-5 relative overflow-hidden">
                <div className="absolute -top-20 -right-20 w-60 h-60 rounded-full bg-red-100/30 blur-3xl pointer-events-none" />
                <div className="relative flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-ink-800 flex items-center gap-2">
                    <div className="w-6 h-6 rounded-md bg-gradient-to-br from-red-500 to-orange-500 flex items-center justify-center">
                      <Target className="w-3.5 h-3.5 text-white" />
                    </div>
                    风险溯源
                  </h3>
                  <span className="text-[11px] text-ink-500 flex items-center gap-1.5">
                    <ImageIcon className="w-3 h-3" />
                    {activeInsp ? getStoreNameById(activeInsp.id) : "未知门店"} · {activeRisk.category}
                  </span>
                </div>
                <div className="relative rounded-xl overflow-hidden bg-ink-100" style={{ height: 320 }}>
                  <img src={activePhoto.url} alt={activePhoto.category} className="w-full h-full object-cover" />
                  {activePhoto.box && (
                    <div className="absolute inset-0 pointer-events-none">
                      <div
                        className="absolute border-[3px] border-red-500 rounded transition-all duration-500"
                        style={{
                          left: `${activePhoto.box.x}%`,
                          top: `${activePhoto.box.y}%`,
                          width: `${activePhoto.box.w}%`,
                          height: `${activePhoto.box.h}%`,
                          boxShadow: "0 0 0 9999px rgba(15, 23, 42, 0.3), inset 0 0 0 1px rgba(255, 255, 255, 0.3)",
                        }}
                      >
                        <span className="absolute -top-7 left-0 inline-flex items-center gap-1 bg-red-500 text-white text-[11px] font-semibold px-2 py-0.5 rounded shadow-glow-red">
                          <Target className="w-3 h-3" /> 问题位置
                        </span>
                      </div>
                    </div>
                  )}
                  <div className="absolute top-3 right-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-black/60 backdrop-blur-sm text-white text-xs font-medium">
                    <ImageIcon className="w-3 h-3" />
                    {activePhoto.category}
                  </div>
                </div>
                {/* AI 识别 */}
                <div className="mt-3 relative rounded-xl bg-gradient-to-br from-brand-50/60 to-cyan-50/40 border border-brand-100/60 p-4 overflow-hidden">
                  <div className="absolute -top-10 -right-10 w-32 h-32 bg-cyan-200/20 rounded-full blur-2xl pointer-events-none" />
                  <div className="relative flex items-center gap-2 mb-2">
                    <div className="w-5 h-5 rounded-md bg-gradient-to-br from-cyan-500 to-brand-700 flex items-center justify-center">
                      <ScanText className="w-3 h-3 text-white" />
                    </div>
                    <span className="text-sm font-semibold text-ink-800">AI 识别结果</span>
                    <span className={cn(
                      "ml-auto text-xs px-2 py-0.5 rounded-full font-semibold",
                      activePhoto.confidence >= 0.9
                        ? "bg-emerald-100 text-emerald-700 border border-emerald-200"
                        : "bg-amber-100 text-amber-700 border border-amber-200"
                    )}>
                      置信度 {(activePhoto.confidence * 100).toFixed(0)}%
                    </span>
                  </div>
                  <p className="text-sm text-ink-700 leading-relaxed">{activePhoto.aiResult}</p>
                </div>
              </Card>

              {/* 风险详情 */}
              <Card className="p-5">
                <div className="flex items-center gap-2.5 mb-3">
                  <RiskLevelBadge level={activeRisk.level} />
                  <RiskStatusBadge status={activeRisk.status} />
                  <span className="text-xs text-ink-500 font-mono">置信度 {(activeRisk.confidence * 100).toFixed(0)}%</span>
                </div>
                <p className="text-base text-ink-900 font-semibold mb-4 leading-relaxed">{activeRisk.description}</p>

                <div className="grid grid-cols-2 gap-3">
                  <div className="bg-gradient-to-br from-ink-50 to-white border border-ink-200/60 rounded-xl p-3.5">
                    <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase flex items-center gap-1 mb-1.5">
                      <BookOpen className="w-3 h-3" /> 判定依据
                    </p>
                    <p className="text-sm text-ink-700 leading-relaxed">{activeRisk.basis}</p>
                  </div>
                  <div className="bg-gradient-to-br from-emerald-50/60 to-white border border-emerald-200/60 rounded-xl p-3.5">
                    <p className="text-[10px] text-emerald-600 font-semibold tracking-wider uppercase flex items-center gap-1 mb-1.5">
                      <Lightbulb className="w-3 h-3" /> 整改建议
                    </p>
                    <p className="text-sm text-ink-700 leading-relaxed">{activeRisk.suggestion}</p>
                  </div>
                </div>

                {/* 状态流转 */}
                <div className="mt-5">
                  <div className="flex items-center justify-between mb-3">
                    <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase">整改状态流转</p>
                    <span className="text-[10px] text-ink-400 font-mono">
                      {STATUS_FLOW.findIndex((x) => x.status === activeRisk.status) + 1} / {STATUS_FLOW.length}
                    </span>
                  </div>
                  
                  {/* 进度条 */}
                  <ProgressBar
                    value={STATUS_FLOW.findIndex((x) => x.status === activeRisk.status) + 1}
                    max={STATUS_FLOW.length}
                    color="brand"
                    size="sm"
                    className="mb-4"
                  />
                  
                  {/* 时间线式状态 */}
                  <div className="relative flex items-center justify-between">
                    {STATUS_FLOW.map((s, i) => {
                      const currentIdx = STATUS_FLOW.findIndex((x) => x.status === activeRisk.status);
                      const isPassed = i <= currentIdx;
                      const isCurrent = i === currentIdx;
                      return (
                        <div key={s.status} className="flex flex-col items-center relative z-10">
                          <div className={cn(
                            "w-7 h-7 rounded-full flex items-center justify-center transition-all duration-500",
                            isPassed
                              ? "bg-gradient-to-br from-brand-600 to-cyan-500 shadow-[0_0_12px_rgba(30,58,138,0.4)]"
                              : "bg-ink-100 border-2 border-ink-200"
                          )}>
                            {isPassed ? (
                              <Check className="w-3.5 h-3.5 text-white" />
                            ) : (
                              <Circle className="w-3 h-3 text-ink-300" />
                            )}
                            {isCurrent && (
                              <span className="absolute w-10 h-10 rounded-full bg-brand-400/30 animate-ping" />
                            )}
                          </div>
                          <span className={cn(
                            "text-[10px] mt-1.5 font-semibold whitespace-nowrap",
                            isPassed ? "text-brand-700" : "text-ink-300"
                          )}>
                            {s.label}
                          </span>
                        </div>
                      );
                    })}
                    {/* 连接线 */}
                    <div className="absolute top-3.5 left-0 right-0 h-0.5 bg-ink-100 -z-0" />
                    <div 
                      className="absolute top-3.5 left-0 h-0.5 bg-gradient-to-r from-brand-600 to-cyan-500 transition-all duration-700 -z-0"
                      style={{ 
                        width: `${(STATUS_FLOW.findIndex((x) => x.status === activeRisk.status) / (STATUS_FLOW.length - 1)) * 100}%` 
                      }}
                    />
                  </div>
                </div>

                {/* 整改闭环操作面板 */}
                <RectificationPanel risk={activeRisk} />
              </Card>

              {/* 整改前后对比 */}
              {activeRisk.fixedPhotoUrl && (
                <Card className="p-5 relative overflow-hidden">
                  <div className="absolute -top-20 -right-20 w-60 h-60 rounded-full bg-emerald-100/40 blur-3xl pointer-events-none" />
                  <div className="relative">
                    <h3 className="text-sm font-semibold text-ink-800 mb-1 flex items-center gap-2">
                      <div className="w-6 h-6 rounded-md bg-gradient-to-br from-emerald-500 to-emerald-600 flex items-center justify-center shadow-[0_0_12px_rgba(16,185,129,0.4)]">
                        <CheckCircle2 className="w-3.5 h-3.5 text-white" />
                      </div>
                      整改验证 · 前后对比
                    </h3>
                    <p className="text-xs text-ink-500 mb-3 flex items-center gap-1.5">
                      <Sparkles className="w-3 h-3 text-amber-500" /> 拖动滑块对比整改前后的变化
                    </p>
                    <BeforeAfterSlider
                      beforeUrl={activePhoto.url}
                      afterUrl={activeRisk.fixedPhotoUrl}
                      height={340}
                    />
                    {activeRisk.fixNote && (
                      <div className="mt-3 relative rounded-xl bg-gradient-to-r from-emerald-50 to-cyan-50/40 border border-emerald-200/60 p-3.5 overflow-hidden">
                        <div className="absolute -top-10 -right-10 w-32 h-32 bg-emerald-200/30 rounded-full blur-2xl pointer-events-none" />
                        <div className="relative flex items-center gap-2 mb-1.5">
                          <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                          <span className="text-xs font-semibold text-emerald-700">整改说明</span>
                          {activeRisk.fixedTime && (
                            <span className="text-xs text-ink-500 flex items-center gap-1 ml-auto">
                              <Clock className="w-3 h-3" />{activeRisk.fixedTime.slice(0, 10)}
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-ink-700 leading-relaxed">{activeRisk.fixNote}</p>
                      </div>
                    )}
                  </div>
                </Card>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// ============ 审计事件配置 ============
const AUDIT_ACTION_CONFIG: Record<AuditEvent["action"], { label: string; icon: typeof CheckCircle2; color: string; bg: string }> = {
  ai_detected: { label: "AI 识别", icon: ScanText, color: "text-cyan-600", bg: "bg-cyan-100" },
  confirm: { label: "确认风险", icon: CheckCircle2, color: "text-blue-600", bg: "bg-blue-100" },
  start_fix: { label: "开始整改", icon: RotateCcw, color: "text-amber-600", bg: "bg-amber-100" },
  submit_fix: { label: "提交整改", icon: CheckCircle2, color: "text-cyan-600", bg: "bg-cyan-100" },
  verify: { label: "验证通过", icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
  reject: { label: "驳回整改", icon: XCircle, color: "text-red-600", bg: "bg-red-100" },
};

// ============ 整改闭环操作面板 ============
function RectificationPanel({ risk }: { risk: import("@/types").Risk }) {
  const {
    confirmRisk,
    startRectification,
    submitRectification,
    verifyRectification,
    rejectRectification,
  } = useStore();
  const task = useRectificationTask(risk.id);
  const auditEvents = useAuditEvents(risk.id);

  // 各步骤的弹窗状态
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [startOpen, setStartOpen] = useState(false);
  const [submitOpen, setSubmitOpen] = useState(false);
  const [rejectOpen, setRejectOpen] = useState(false);

  // 表单状态
  const [confirmLevel, setConfirmLevel] = useState<RiskLevel>(risk.level);
  const [confirmDesc, setConfirmDesc] = useState(risk.description);
  const [assignee, setAssignee] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [fixNote, setFixNote] = useState("");
  const [rejectReason, setRejectReason] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});

  // 切换风险时重置表单
  useEffect(() => {
    setConfirmLevel(risk.level);
    setConfirmDesc(risk.description);
    setAssignee("");
    setDueDate("");
    setFixNote("");
    setRejectReason("");
    setErrors({});
    setConfirmOpen(false);
    setStartOpen(false);
    setSubmitOpen(false);
    setRejectOpen(false);
  }, [risk.id, risk.level, risk.description]);

  // 默认截止日期：3天后
  useEffect(() => {
    if (startOpen && !dueDate) {
      const d = new Date();
      d.setDate(d.getDate() + 3);
      const p = (x: number) => String(x).padStart(2, "0");
      setDueDate(`${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`);
    }
  }, [startOpen, dueDate]);

  const handleConfirm = () => {
    if (!confirmDesc.trim()) {
      setErrors({ confirmDesc: "请输入风险描述" });
      return;
    }
    confirmRisk(risk.id, { level: confirmLevel, description: confirmDesc.trim() });
    setConfirmOpen(false);
  };

  const handleStart = () => {
    const errs: Record<string, string> = {};
    if (!assignee.trim()) errs.assignee = "请输入责任人姓名";
    if (!dueDate) errs.dueDate = "请选择截止日期";
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;
    startRectification(risk.id, { assignee: assignee.trim(), dueDate });
    setStartOpen(false);
  };

  const handleSubmit = () => {
    if (!fixNote.trim()) {
      setErrors({ fixNote: "请填写整改说明" });
      return;
    }
    submitRectification(risk.id, { fixNote: fixNote.trim(), fixedPhotoUrl: "" });
    setFixNote("");
    setSubmitOpen(false);
  };

  const handleReject = () => {
    if (!rejectReason.trim()) {
      setErrors({ rejectReason: "请填写驳回原因" });
      return;
    }
    rejectRectification(risk.id, { rejectReason: rejectReason.trim() });
    setRejectReason("");
    setRejectOpen(false);
  };

  const status = risk.status;

  return (
    <div className="mt-5 pt-5 border-t border-ink-100">
      <div className="flex items-center justify-between mb-3">
        <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase flex items-center gap-1">
          <History className="w-3 h-3" /> 整改闭环操作
        </p>
        {task && task.rejectCount > 0 && (
          <Badge variant="warning" size="sm">已被驳回 {task.rejectCount} 次</Badge>
        )}
      </div>

      {/* 整改任务信息（已开始整改时显示） */}
      {task && (
        <div className="mb-4 rounded-xl bg-gradient-to-br from-amber-50/60 to-white border border-amber-200/60 p-3.5">
          <div className="grid grid-cols-3 gap-3 text-xs">
            <div>
              <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1 flex items-center gap-1">
                <User className="w-3 h-3" /> 责任人
              </p>
              <p className="text-ink-800 font-medium">{task.assignee}</p>
            </div>
            <div>
              <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1 flex items-center gap-1">
                <Calendar className="w-3 h-3" /> 截止日期
              </p>
              <p className="text-ink-800 font-medium font-mono">{task.dueDate}</p>
            </div>
            <div>
              <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1 flex items-center gap-1">
                <Clock className="w-3 h-3" /> 开始时间
              </p>
              <p className="text-ink-800 font-medium font-mono">{task.startedAt?.slice(0, 10) || "—"}</p>
            </div>
          </div>
          {task.rejectReason && (
            <div className="mt-3 pt-3 border-t border-amber-200/60 flex items-start gap-2">
              <AlertCircle className="w-3.5 h-3.5 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-[10px] text-red-600 font-semibold tracking-wider uppercase mb-0.5">最近驳回原因</p>
                <p className="text-xs text-ink-700 leading-relaxed">{task.rejectReason}</p>
              </div>
            </div>
          )}
        </div>
      )}

      {/* 操作按钮（按状态显示） */}
      <div className="flex items-center gap-2 flex-wrap">
        {status === "ai_detected" && (
          <Button variant="gradient" onClick={() => setConfirmOpen(true)} icon={<CheckCircle2 className="w-4 h-4" />}>
            确认风险
          </Button>
        )}
        {status === "confirmed" && (
          <Button variant="gradient" onClick={() => setStartOpen(true)} icon={<RotateCcw className="w-4 h-4" />}>
            开始整改
          </Button>
        )}
        {status === "fixing" && (
          <Button variant="gradient" onClick={() => setSubmitOpen(true)} icon={<CheckCircle2 className="w-4 h-4" />}>
            提交整改
          </Button>
        )}
        {status === "fixed" && (
          <>
            <Button variant="gradient" onClick={() => verifyRectification(risk.id)} icon={<CheckCircle2 className="w-4 h-4" />}>
              验证通过
            </Button>
            <Button variant="secondary" onClick={() => setRejectOpen(true)} icon={<XCircle className="w-4 h-4" />}>
              驳回整改
            </Button>
          </>
        )}
        {status === "verified" && (
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-emerald-50 text-emerald-700 text-xs font-medium">
            <CheckCircle2 className="w-4 h-4" />
            整改闭环已完成
          </div>
        )}
      </div>

      {/* 审计时间线 */}
      {auditEvents.length > 0 && (
        <div className="mt-5">
          <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-3 flex items-center gap-1">
            <History className="w-3 h-3" /> 操作记录
          </p>
          <div className="space-y-2.5">
            {auditEvents.map((evt) => {
              const cfg = AUDIT_ACTION_CONFIG[evt.action];
              const Icon = cfg.icon;
              return (
                <div key={evt.id} className="flex items-start gap-2.5 group">
                  <div className={cn("w-6 h-6 rounded-md flex items-center justify-center flex-shrink-0", cfg.bg)}>
                    <Icon className={cn("w-3.5 h-3.5", cfg.color)} />
                  </div>
                  <div className="flex-1 min-w-0 pb-2 border-b border-ink-100/60 last:border-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-xs font-semibold text-ink-800">{cfg.label}</span>
                      <span className="text-[11px] text-ink-500">{evt.operator}</span>
                      <span className="text-[11px] text-ink-400 font-mono ml-auto">{evt.timestamp}</span>
                    </div>
                    {evt.note && (
                      <p className="text-xs text-ink-600 mt-0.5 leading-relaxed">{evt.note}</p>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 确认风险弹窗 */}
      <Modal
        open={confirmOpen}
        onClose={() => setConfirmOpen(false)}
        title="确认风险"
        size="md"
        footer={
          <>
            <Button variant="ghost" size="md" onClick={() => setConfirmOpen(false)}>取消</Button>
            <Button variant="gradient" size="md" onClick={handleConfirm} icon={<CheckCircle2 className="w-4 h-4" />}>
              确认
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <p className="text-xs text-ink-500">确认风险后进入待整改状态，可在此调整风险等级和描述。</p>
          <div>
            <label className="block text-xs font-medium text-ink-600 mb-1.5">风险等级</label>
            <div className="flex items-center gap-2">
              {(["high", "mid", "low"] as RiskLevel[]).map((lv) => (
                <button
                  key={lv}
                  onClick={() => setConfirmLevel(lv)}
                  className={cn(
                    "px-3 py-1.5 rounded-md text-xs font-medium transition cursor-pointer border",
                    confirmLevel === lv
                      ? lv === "high" ? "bg-red-50 text-red-700 border-red-300" :
                        lv === "mid" ? "bg-orange-50 text-orange-700 border-orange-300" :
                        "bg-yellow-50 text-yellow-700 border-yellow-300"
                      : "bg-white text-ink-500 border-ink-200 hover:border-brand-300"
                  )}
                >
                  {lv === "high" ? "高风险" : lv === "mid" ? "中风险" : "低风险"}
                </button>
              ))}
            </div>
          </div>
          <Textarea
            label="风险描述"
            rows={3}
            value={confirmDesc}
            onChange={(e) => setConfirmDesc(e.target.value)}
            error={errors.confirmDesc}
          />
        </div>
      </Modal>

      {/* 开始整改弹窗 */}
      <Modal
        open={startOpen}
        onClose={() => setStartOpen(false)}
        title="开始整改"
        size="md"
        footer={
          <>
            <Button variant="ghost" size="md" onClick={() => setStartOpen(false)}>取消</Button>
            <Button variant="gradient" size="md" onClick={handleStart} icon={<RotateCcw className="w-4 h-4" />}>
              启动整改
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <p className="text-xs text-ink-500">指定整改责任人和截止日期，进入整改中状态。</p>
          <Input
            label="责任人 *"
            placeholder="如：王店长"
            value={assignee}
            onChange={(e) => setAssignee(e.target.value)}
            error={errors.assignee}
          />
          <div>
            <label className="block text-xs font-medium text-ink-600 mb-1.5">截止日期 *</label>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              className={cn(
                "w-full px-3.5 py-2.5 rounded-lg border text-sm transition-all duration-200 outline-none",
                errors.dueDate
                  ? "border-red-300 focus:border-red-400 focus:ring-2 focus:ring-red-100"
                  : "border-ink-200 focus:border-brand-400 focus:ring-2 focus:ring-brand-100"
              )}
            />
            {errors.dueDate && <p className="text-xs text-red-500 mt-1">{errors.dueDate}</p>}
          </div>
        </div>
      </Modal>

      {/* 提交整改弹窗 */}
      <Modal
        open={submitOpen}
        onClose={() => setSubmitOpen(false)}
        title="提交整改"
        size="md"
        footer={
          <>
            <Button variant="ghost" size="md" onClick={() => setSubmitOpen(false)}>取消</Button>
            <Button variant="gradient" size="md" onClick={handleSubmit} icon={<CheckCircle2 className="w-4 h-4" />}>
              提交
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-lg bg-cyan-50/60 border border-cyan-200/60">
            <Sparkles className="w-4 h-4 text-cyan-600 flex-shrink-0 mt-0.5" />
            <p className="text-xs text-ink-600">
              提交整改后系统将自动生成整改后样本照片（演示），进入"已整改"状态等待验证。
            </p>
          </div>
          <Textarea
            label="整改说明 *"
            rows={4}
            placeholder="请描述本次整改采取的措施、处理结果等..."
            value={fixNote}
            onChange={(e) => setFixNote(e.target.value)}
            error={errors.fixNote}
          />
        </div>
      </Modal>

      {/* 驳回整改弹窗 */}
      <Modal
        open={rejectOpen}
        onClose={() => setRejectOpen(false)}
        title="驳回整改"
        size="md"
        footer={
          <>
            <Button variant="ghost" size="md" onClick={() => setRejectOpen(false)}>取消</Button>
            <Button variant="secondary" size="md" onClick={handleReject} icon={<XCircle className="w-4 h-4" />}>
              确认驳回
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-lg bg-red-50/60 border border-red-200/60">
            <AlertCircle className="w-4 h-4 text-red-500 flex-shrink-0 mt-0.5" />
            <p className="text-xs text-ink-600">
              驳回后状态将退回"整改中"，需重新提交整改说明和样本。
            </p>
          </div>
          <Textarea
            label="驳回原因 *"
            rows={4}
            placeholder="请说明为何驳回本次整改..."
            value={rejectReason}
            onChange={(e) => setRejectReason(e.target.value)}
            error={errors.rejectReason}
          />
        </div>
      </Modal>
    </div>
  );
}
