import { useState, useRef, useEffect, useCallback } from "react";
import { MoveHorizontal, Play, Pause, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

export default function BeforeAfterSlider({
  beforeUrl,
  afterUrl,
  height = 300,
  autoPlay = false,
  showControls = true,
}: {
  beforeUrl: string;
  afterUrl: string;
  height?: number;
  autoPlay?: boolean;
  showControls?: boolean;
}) {
  const [position, setPosition] = useState(50);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);
  const playDirection = useRef(1);
  const animationRef = useRef<number | null>(null);

  // 自动播放动画
  const animate = useCallback(() => {
    setPosition((prev) => {
      let next = prev + playDirection.current * 0.4;
      if (next >= 100) {
        next = 100;
        playDirection.current = -1;
      } else if (next <= 0) {
        next = 0;
        playDirection.current = 1;
      }
      return next;
    });
    animationRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    if (isPlaying) {
      animationRef.current = requestAnimationFrame(animate);
    } else if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [isPlaying, animate]);

  // 自动播放初始
  useEffect(() => {
    if (autoPlay) {
      const timer = setTimeout(() => setIsPlaying(true), 800);
      return () => clearTimeout(timer);
    }
  }, [autoPlay]);

  // 键盘控制：只在容器聚焦时响应，避免全局监听影响其他输入
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        setPosition((p) => Math.max(0, p - 2));
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        setPosition((p) => Math.min(100, p + 2));
      } else if (e.key === "Home") {
        e.preventDefault();
        setPosition(0);
      } else if (e.key === "End") {
        e.preventDefault();
        setPosition(100);
      } else if (e.key === " ") {
        e.preventDefault();
        setIsPlaying((p) => !p);
      }
    };
    container.addEventListener("keydown", handleKeyDown);
    return () => container.removeEventListener("keydown", handleKeyDown);
  }, []);

  const handleMove = (clientX: number) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = clientX - rect.left;
    const pct = Math.max(0, Math.min(100, (x / rect.width) * 100));
    setPosition(pct);
  };

  const handleMouseDown = () => { 
    isDragging.current = true; 
    setIsPlaying(false);
  };
  const handleMouseUp = () => { isDragging.current = false; };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging.current) handleMove(e.clientX);
  };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (isDragging.current && e.touches[0]) handleMove(e.touches[0].clientX);
  };

  const handleReset = () => {
    setIsPlaying(false);
    setPosition(50);
  };

  const togglePlay = () => {
    setIsPlaying((p) => !p);
  };

  return (
    <div
      ref={containerRef}
      className="relative rounded-xl overflow-hidden select-none cursor-ew-resize group outline-none focus-visible:ring-2 focus-visible:ring-brand-400 focus-visible:ring-offset-2"
      style={{ height }}
      tabIndex={0}
      role="slider"
      aria-label="整改前后对比滑块"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(position)}
      aria-valuetext={`整改前 ${Math.round(position)}%，整改后 ${Math.round(100 - position)}%`}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { handleMouseUp(); setIsHovered(false); }}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleMouseUp}
      onMouseEnter={() => setIsHovered(true)}
    >
      {/* 整改后（底层） */}
      <img src={afterUrl} alt="整改后" className="absolute inset-0 w-full h-full object-cover" draggable={false} />
      
      {/* 整改后标签 */}
      <div className={cn(
        "absolute top-3 right-3 z-10 transition-all duration-300",
        isHovered ? "opacity-100 translate-y-0" : "opacity-0 -translate-y-2"
      )}>
        <span className="inline-flex items-center gap-1.5 bg-emerald-500/90 backdrop-blur-sm text-white text-xs font-semibold px-2.5 py-1 rounded-lg shadow-lg">
          <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
          整改后
        </span>
      </div>

      {/* 整改前（上层，clip 控制） */}
      <div
        className="absolute inset-0 overflow-hidden"
        style={{ width: `${position}%` }}
      >
        <img
          src={beforeUrl}
          alt="整改前"
          className="absolute inset-0 h-full object-cover"
          style={{ width: containerRef.current?.offsetWidth || "100%" }}
          draggable={false}
        />
        {/* 整改前标签 */}
        <div className={cn(
          "absolute top-3 left-3 transition-all duration-300",
          isHovered ? "opacity-100 translate-y-0" : "opacity-0 -translate-y-2"
        )}>
          <span className="inline-flex items-center gap-1.5 bg-red-500/90 backdrop-blur-sm text-white text-xs font-semibold px-2.5 py-1 rounded-lg shadow-lg">
            <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
            整改前
          </span>
        </div>
      </div>

      {/* 滑块分割线 */}
      <div
        className="absolute top-0 bottom-0 pointer-events-none z-20"
        style={{ left: `${position}%`, transform: "translateX(-50%)" }}
      >
        {/* 发光线 */}
        <div className="absolute top-0 bottom-0 left-1/2 -translate-x-1/2 w-1 bg-gradient-to-b from-transparent via-white to-transparent opacity-80" />
        <div className="absolute top-0 bottom-0 left-1/2 -translate-x-1/2 w-6 bg-gradient-to-b from-white/0 via-white/20 to-white/0 blur-sm" />
        
        {/* 滑块按钮 */}
        <div className={cn(
          "absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-11 h-11 rounded-full bg-gradient-to-br from-brand-700 to-cyan-600 border-[3px] border-white shadow-[0_4px_20px_rgba(30,58,138,0.5)] flex items-center justify-center transition-all duration-300",
          isHovered ? "scale-110 shadow-[0_6px_28px_rgba(30,58,138,0.6)]" : "scale-100"
        )}>
          <MoveHorizontal className={cn(
            "w-5 h-5 text-white transition-transform duration-300",
            isPlaying && "animate-pulse"
          )} />
        </div>
      </div>

      {/* 控制栏 */}
      {showControls && (
        <div className={cn(
          "absolute bottom-3 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 px-3 py-2 rounded-xl bg-black/40 backdrop-blur-md border border-white/10 transition-all duration-300",
          isHovered ? "opacity-100 translate-y-0" : "opacity-0 translate-y-2"
        )}>
          <button
            onClick={togglePlay}
            className="w-7 h-7 rounded-lg bg-white/20 hover:bg-white/30 flex items-center justify-center text-white transition-colors cursor-pointer"
            title={isPlaying ? "暂停 (空格)" : "播放 (空格)"}
          >
            {isPlaying ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5 ml-0.5" />}
          </button>
          <button
            onClick={handleReset}
            className="w-7 h-7 rounded-lg bg-white/20 hover:bg-white/30 flex items-center justify-center text-white transition-colors cursor-pointer"
            title="重置"
          >
            <RotateCcw className="w-3.5 h-3.5" />
          </button>
          <div className="w-px h-4 bg-white/20" />
          <span className="text-white/80 text-[10px] font-mono tabular-nums min-w-[36px] text-center">
            {Math.round(position)}%
          </span>
        </div>
      )}

      {/* 滑块控制条 */}
      <input
        type="range"
        min={0}
        max={100}
        value={position}
        onChange={(e) => {
          setPosition(Number(e.target.value));
          setIsPlaying(false);
        }}
        onMouseDown={handleMouseDown}
        className="compare-slider absolute inset-0 w-full h-full opacity-0 cursor-ew-resize"
      />

      {/* 角标装饰 */}
      <div className="absolute top-2 left-2 w-4 h-4 border-l-2 border-t-2 border-white/40 rounded-tl-lg pointer-events-none" />
      <div className="absolute top-2 right-2 w-4 h-4 border-r-2 border-t-2 border-white/40 rounded-tr-lg pointer-events-none" />
      <div className="absolute bottom-2 left-2 w-4 h-4 border-l-2 border-b-2 border-white/40 rounded-bl-lg pointer-events-none" />
      <div className="absolute bottom-2 right-2 w-4 h-4 border-r-2 border-b-2 border-white/40 rounded-br-lg pointer-events-none" />
    </div>
  );
}
